<script setup>
import {ref,watch,onMounted,onUnmounted} from 'vue'
import {useRouter,useRoute} from 'vue-router'
import {useArcade} from '../stores/arcade'
import PointHistory from '../components/PointHistory.vue'
import {api} from '../lib/api'
import GameHeader from '../components/GameHeader.vue'
import CharacterPicker from '../components/CharacterPicker.vue'
import PartnerImage from '../components/PartnerImage.vue'
const s=useArcade(),router=useRouter(),route=useRoute()
watch(()=>!!s.user,value=>document.documentElement.classList.toggle('profile-mode',value),{immediate:true});onUnmounted(()=>document.documentElement.classList.remove('profile-mode'))
const online=ref([]);let onlineTimer;async function loadOnline(){try{online.value=(await api('/online')).items}catch{}}onMounted(()=>{loadOnline();onlineTimer=setInterval(loadOnline,15000)});onUnmounted(()=>clearInterval(onlineTimer));
const selected=ref('piplup')
const mode=ref('login'),id=ref(''),password=ref(''),nickname=ref(s.user?.nickname||''),confirm=ref(''),error=ref(''),message=ref(''),busy=ref(false)
watch(mode,()=>{error.value='';message.value='';password.value='';confirm.value=''})
async function submit(){error.value='';message.value='';busy.value=true;try{if(mode.value==='register'){if(password.value!==confirm.value)throw Error('비밀번호 확인이 일치하지 않아요.');await s.register(id.value,password.value,nickname.value);await s.selectCharacter(selected.value)}else await s.login(id.value,password.value);password.value='';confirm.value='';await router.replace(s.user.role==='admin'?'/admin':'/student')}catch(e){error.value=e.message}finally{busy.value=false}}
async function save(){error.value='';message.value='';try{await s.rename(nickname.value);message.value='닉네임을 저장했어요!'}catch(e){error.value=e.message}}
async function logout(){await s.logout();await router.replace('/account')}
</script>
<template><template v-if="s.user"><section class="profile-page"><div class="profile-page-title"><h1>내 포켓</h1><RouterLink :to="s.user.role==='admin'?'/admin':'/student'" class="button light">{{s.user.role==='admin'?'관리자 페이지':'내 학습'}} →</RouterLink></div><div class="profile-layout"><section class="panel profile-info"><div v-if="s.user.role==='student'" class="profile-partner"><PartnerImage size="avatar"/></div><h2>{{s.user.nickname}}님의 포켓</h2><p class="profile-login">@{{s.user.login}}</p><div class="profile-summary"><b>🪙 {{s.data.coins.toLocaleString()}} P</b><b v-if="s.user.role==='student'">Lv.{{s.level}}</b></div><form @submit.prevent="save"><label for="nickname">닉네임</label><input id="nickname" v-model="nickname" minlength="2" maxlength="20" required autocomplete="nickname"/><button type="submit">닉네임 저장</button></form><p v-if="s.data.legacyMigration" class="notice">기존 기록 이전 {{s.data.legacyMigration.status==='approved'?'승인 완료':'관리자 승인 대기'}} · {{s.data.legacyMigration.coins}} P</p><p v-if="error" class="account-error" role="alert">{{error}}</p><p v-if="message" class="account-success" role="status">{{message}}</p><button class="text-button" @click="logout">로그아웃</button></section><section v-if="s.user.role==='student'" class="panel profile-characters"><h2>함께할 파트너</h2><CharacterPicker :model-value="s.partner.id" :locked="s.data.partnerLocked" @update:model-value="s.selectCharacter"/></section></div></section></template><section v-else class="login-dex" aria-label="Spokemon 로그인"><div class="login-dex-top" aria-hidden="true"><div class="login-dex-lens"></div><div class="login-dex-leds"><i></i><i></i><i></i></div></div><div class="login-dex-body"><div class="login-dex-screen"><div class="login-screen-lights" aria-hidden="true"><i></i><i></i></div><div class="login-screen-scroll"><div class="dex-form-column"><img class="dex-login-logo" src="/images/pokemon-logo.png" alt="Spokemon"/><div class="account-tabs"><button :class="{selected:mode==='login'}" @click="mode='login'">로그인</button><button :class="{selected:mode==='register'}" @click="mode='register'">회원가입</button></div><h2>{{mode==='login'?'트레이너 로그인':'새 트레이너 등록'}}</h2><form @submit.prevent="submit"><label for="login-id">아이디</label><input id="login-id" v-model="id" required minlength="3" maxlength="20" pattern="[a-zA-Z0-9_]{3,20}" autocomplete="username" placeholder="영문·숫자·밑줄 3~20자"/><template v-if="mode==='register'"><label for="new-nickname">닉네임</label><input id="new-nickname" v-model="nickname" required minlength="2" maxlength="12" autocomplete="nickname" placeholder="게임에서 사용할 이름 (2~12자)"/></template><label for="password">비밀번호</label><input id="password" v-model="password" type="password" required minlength="8" maxlength="72" :autocomplete="mode==='register'?'new-password':'current-password'" placeholder="8자 이상"/><template v-if="mode==='register'"><label for="password-confirm">비밀번호 확인</label><input id="password-confirm" v-model="confirm" type="password" required minlength="8" maxlength="72" autocomplete="new-password"/></template><CharacterPicker v-if="mode==='register'" v-model="selected"/><button type="submit" :disabled="busy">{{busy?'잠시만 기다려 주세요…':mode==='login'?'로그인하고 플레이':'가입하고 시작하기'}}</button></form><p v-if="error" class="account-error" role="alert">{{error}}</p><p v-if="message" class="account-success" role="status">{{message}}</p><p class="dex-auth-note">학생은 회원가입 후 관리자에게 기수 배정을 요청해 주세요. 기존 로컬 계정으로 로그인하면 기록 이전을 신청합니다.</p></div></div></div><aside class="login-dex-side" aria-label="파트너 미리보기"><div class="dex-side-frame"><div class="dex-side-screen"><PartnerImage :character="selected"/></div><div class="dex-side-controls" aria-hidden="true"><i></i><span></span><span></span></div></div><div class="dex-side-note"><h3>MY PARTNER</h3><p>함께할 포켓몬은 회원가입에서 선택해요.<br/>이후 5,000포인트로 변경할 수 있어요.</p></div><div class="dex-side-grid" aria-label="접속중인 학생"><span v-for="i in 9" :key="i" :class="['dex-side-key',{'online-student':online[i-1]}]"><template v-if="online[i-1]"><PartnerImage :character="online[i-1].character"/><small>{{online[i-1].login}}</small></template><i v-else class="dex-mini-ball" aria-hidden="true"></i></span></div></aside></div></section></template>
